parameters.jsCode:
const input = $('Build Normalized Fields').item.json;
const cfg = $('Triage Rules Config').item.json;

// Convert comma-separated string OR array -> clean lowercase array
function toList(value) {
  if (Array.isArray(value)) {
    return value
      .map(v => String(v || '').trim().toLowerCase())
      .filter(Boolean);
  }

  if (value == null || value === '') return [];

  return String(value)
    .split(',')
    .map(v => v.trim().toLowerCase())
    .filter(Boolean);
}

// Convert rules string JSON OR array -> array
function toRules(value) {
  if (Array.isArray(value)) return value;
  if (value == null || value === '') return [];

  try {
    const parsed = JSON.parse(String(value));
    return Array.isArray(parsed) ? parsed : [];
  } catch (e) {
    return [];
  }
}

// Config fields can now all be String
const rules = toRules(cfg.rules);
const allowlist = toList(cfg.allowlist_domains);
const blocklistSenders = toList(cfg.blocklist_senders);
const blocklistDomains = toList(cfg.blocklist_domains);
const blocklistHeaderKeywords = toList(cfg.blocklist_header_keywords);
const minBodyChars = Number(cfg.min_body_chars || 10);

// Normalize headers to lowercase keys
const rawHeaders = input.headers || {};
const headers = {};

for (const [key, value] of Object.entries(rawHeaders)) {
  headers[String(key).toLowerCase()] = value;
}

const sender = String(input.sender || '').toLowerCase().trim();
const senderDomain = sender.includes('@')
  ? sender.split('@').pop().trim()
  : '';

const signals = [];
const matchedRuleIds = [];

// Blocklist sender check
if (blocklistSenders.includes(sender)) {
  return [{
    json: {
      ...input,
      triage_decision: "not_ticket",
      triage_reason: "Sender in blocklist",
      triage_signals: ["blocklist_sender"],
      triage_matched_rule_ids: ["BLOCKLIST_SENDER"],
      triage_layer: "rules"
    }
  }];
}

// Blocklist domain check
if (blocklistDomains.includes(senderDomain)) {
  return [{
    json: {
      ...input,
      triage_decision: "not_ticket",
      triage_reason: "Sender domain in blocklist",
      triage_signals: ["blocklist_domain"],
      triage_matched_rule_ids: ["BLOCKLIST_DOMAIN"],
      triage_layer: "rules"
    }
  }];
}

// Blocklist header keyword check
const headerSearchText = [
  input.subject || '',
  ...Object.values(headers).map(v => String(v || ''))
].join(' ').toLowerCase();

const matchedHeaderKeyword = blocklistHeaderKeywords.find(keyword =>
  headerSearchText.includes(keyword)
);

if (matchedHeaderKeyword) {
  return [{
    json: {
      ...input,
      triage_decision: "not_ticket",
      triage_reason: `Header contains blocklisted keyword: ${matchedHeaderKeyword}`,
      triage_signals: ["blocklist_header_keyword"],
      triage_matched_rule_ids: ["BLOCKLIST_HEADER_KEYWORD"],
      triage_layer: "rules"
    }
  }];
}

// Allowlist domain check
if (allowlist.includes(senderDomain)) {
  return [{
    json: {
      ...input,
      triage_decision: "ticket",
      triage_reason: "Sender domain in allowlist",
      triage_signals: ["allowlist_domain"],
      triage_matched_rule_ids: ["ALLOWLIST_OVERRIDE"],
      triage_layer: "rules"
    }
  }];
}

// Rule evaluation
let decision = "ambiguous";
let reason = "";

function evaluate(rule) {
  if (!rule || rule.enabled === false) return false;

  const ct = rule.check_type;
  const field = String(rule.field || '').toLowerCase();
  const pat = rule.pattern;

  if (ct === "header_exists") {
    return headers[field] != null && String(headers[field]).trim() !== '';
  }

  if (ct === "header_in") {
    const headerValue = String(headers[field] || '').toLowerCase().trim();
    const patterns = toList(pat);
    return patterns.includes(headerValue);
  }

  if (ct === "sender_regex") {
    try {
      return new RegExp(String(pat || ''), 'i').test(input.sender || '');
    } catch {
      return false;
    }
  }

  if (ct === "subject_regex") {
    try {
      return new RegExp(String(pat || ''), 'i').test(input.subject || '');
    } catch {
      return false;
    }
  }

  if (ct === "body_min_length") {
    return String(input.body_excerpt || '').trim().length < minBodyChars;
  }

  return false;
}

 for (const rule of rules) {
  if (evaluate(rule)) {
    signals.push(rule.signal);
    matchedRuleIds.push(rule.id);

    if (decision === "ambiguous") {
      decision = rule.decision;
      reason = rule.reason;
    }
  }
}

return [{
  json: {
    ...input,
    triage_decision: decision,
    triage_reason: reason,
    triage_signals: signals,
    triage_matched_rule_ids: matchedRuleIds,
    triage_layer: "rules"
  }
}];

