- next_action must be imperative and concrete.
- summary <= 200 chars, factual, no opinion.

assignments.value:
={{ (() => {
  const docs = Array.isArray($json.matches) ? $json.matches : [];
  return docs
    .filter(m => Number((m.score ?? m.similarity ?? (m.metadata && m.metadata.score) ?? 0)) >= $('Merge System Config').item.json.dedup_threshold)
    .slice(0, $('Merge System Config').item.json.repeat_cluster_cap)
    .map(m => {
      const ticketId = (m.document && m.document.metadata && m.document.metadata.ticket_id) || (m.metadata && m.metadata.ticket_id) || m.ticket_id || m.id || 'UNKNOWN';
      const score = Number((m.score ?? m.similarity ?? (m.metadata && m.metadata.score) ?? 0)).toFixed(2);
      return ticketId + ' (' + score + ')';
    })
    .join(', ');
})() }}

